// @TITLE@ - the game's kit configuration (the Unity counterpart of the Godot project.godot [coddy_ads] block).
// U0 skeleton: release ids stay EMPTY until the Patron creates the real ones (P4/P8; never a made-up id, games/CLAUDE.md §5);
// a release build fails closed while they are empty (@NS@AndroidBuild + jenkins/preflight.py --production).
// Generated by games/tools/unity/new_game.sh - the game owns this file from now on.
using System.Collections.Generic;
using CoddyKit;
using CoddyKit.Ads;
using UnityEngine;

namespace @NS@.App
{
    public static class @NS@GameConfig
    {
        public const string AppId = "@SLUG@";                 // ads-config X-App-ID, house-ad host id
        public const string Package = "@PACKAGE@";
        public const string ProductName = "@TITLE@";          // F0 / P6 decide the store title
        public const bool Landscape = @LANDSCAPE@;             // @ORIENT@ only

        // ---- P4/P8 (Patron): real ids. Keep the constant names: jenkins/preflight.py reads them. ----
        public const string AdMobRewardedAndroid = "";        // ADMOB_REWARDED_<SLUG>_ANDROID (store-automation/.env)
        public const string RevenueCatAndroidKey = "";        // RC public SDK key (goog_...)

        /// <summary>RC entitlements that remove forced ads (games/CLAUDE.md §3/§8): noads only (granted by Remove Ads / premium / pass / bundle).</summary>
        public static readonly string[] AdFreeEntitlements = { "noads" };

        /// <summary>P4 fills the placements from data (games/tools/REWARDED_ADS_STRATEGY.md); empty = no rewarded placement yet.</summary>
        public static Dictionary<string, RewardedLimit> RewardedLimits() => new Dictionary<string, RewardedLimit>();

        public static readonly string[] Languages = { "en", "tr", "de", "es", "fr", "pt", "ru", "ja", "ko", "hi" };

        /// <summary>Until the P5 localisation exists: the device language if it is one of the 10, else English.</summary>
        public static string DeviceLanguage()
        {
            switch (Application.systemLanguage)
            {
                case SystemLanguage.Turkish: return "tr";
                case SystemLanguage.German: return "de";
                case SystemLanguage.Spanish: return "es";
                case SystemLanguage.French: return "fr";
                case SystemLanguage.Portuguese: return "pt";
                case SystemLanguage.Russian: return "ru";
                case SystemLanguage.Japanese: return "ja";
                case SystemLanguage.Korean: return "ko";
                case SystemLanguage.Hindi: return "hi";
                default: return "en";
            }
        }

        public static KitConfig Kit()
        {
            return new KitConfig
            {
                AppId = AppId,
                Platform = "android",
                Kids = false,
                RewardedUnitRelease = AdMobRewardedAndroid,
                RewardedLimits = RewardedLimits(),
                RevenueCatApiKey = RevenueCatAndroidKey,
                AdFreeEntitlements = AdFreeEntitlements,
                UiLanguage = DeviceLanguage,
                ReviewMinPlayS = 240.0,
            };
        }
    }
}
